CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE IF NOT EXISTS departments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name TEXT NOT NULL UNIQUE,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS designations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name TEXT NOT NULL UNIQUE,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS users (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(),email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,full_name TEXT NOT NULL,
 role TEXT NOT NULL CHECK(role IN('MANAGER','EMPLOYEE')),access_role TEXT NOT NULL DEFAULT 'EMPLOYEE',active BOOLEAN NOT NULL DEFAULT TRUE,
 session_version INTEGER NOT NULL DEFAULT 1,must_change_password BOOLEAN NOT NULL DEFAULT FALSE,two_factor_enabled BOOLEAN NOT NULL DEFAULT FALSE,two_factor_email TEXT,
 last_login_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE TABLE IF NOT EXISTS employees (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,employee_code TEXT NOT NULL UNIQUE,
 department_id UUID REFERENCES departments(id) ON DELETE SET NULL,designation TEXT,phone TEXT,official_phone TEXT,personal_phone TEXT,personal_email TEXT,date_of_joining DATE,
 employment_type TEXT NOT NULL DEFAULT 'FULL_TIME',manager_id UUID REFERENCES users(id) ON DELETE SET NULL,wfh_allowed BOOLEAN NOT NULL DEFAULT FALSE,wfh_notes TEXT,
 emergency_contact TEXT,address TEXT,holiday_region TEXT NOT NULL DEFAULT 'INDIA' CHECK(holiday_region IN('INDIA','US','BOTH')),weekly_off_days INTEGER[] NOT NULL DEFAULT ARRAY[0],
 probation_end_date DATE,probation_status TEXT NOT NULL DEFAULT 'NOT_SET',confirmed_at TIMESTAMPTZ,status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','NOTICE','INACTIVE')),
 created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE TABLE IF NOT EXISTS attendance (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(),employee_id UUID NOT NULL REFERENCES employees(id) ON DELETE CASCADE,work_date DATE NOT NULL DEFAULT CURRENT_DATE,check_in TIMESTAMPTZ,check_out TIMESTAMPTZ,
 work_mode TEXT NOT NULL DEFAULT 'OFFICE' CHECK(work_mode IN('OFFICE','WFH')),status TEXT NOT NULL DEFAULT 'PRESENT' CHECK(status IN('PRESENT','HALF_DAY','ABSENT','LEAVE','HOLIDAY')),note TEXT,
 adjusted_by UUID REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(employee_id,work_date)
);
CREATE TABLE IF NOT EXISTS attendance_settings (id INTEGER PRIMARY KEY DEFAULT 1 CHECK(id=1),office_start TIME NOT NULL DEFAULT '09:30',office_end TIME NOT NULL DEFAULT '18:30',grace_minutes INTEGER NOT NULL DEFAULT 15,half_day_min_hours NUMERIC(4,2) NOT NULL DEFAULT 4,full_day_min_hours NUMERIC(4,2) NOT NULL DEFAULT 8,regularization_enabled BOOLEAN NOT NULL DEFAULT TRUE,updated_by UUID REFERENCES users(id) ON DELETE SET NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS attendance_regularizations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),employee_id UUID NOT NULL REFERENCES employees(id) ON DELETE CASCADE,work_date DATE NOT NULL,requested_check_in TIMESTAMPTZ,requested_check_out TIMESTAMPTZ,requested_work_mode TEXT NOT NULL DEFAULT 'OFFICE',reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING',manager_comment TEXT,reviewed_by UUID REFERENCES users(id) ON DELETE SET NULL,reviewed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS leave_types (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name TEXT NOT NULL UNIQUE,code TEXT NOT NULL UNIQUE,default_days NUMERIC(6,2) NOT NULL DEFAULT 0,paid BOOLEAN NOT NULL DEFAULT TRUE,allow_half_day BOOLEAN NOT NULL DEFAULT TRUE,carry_forward BOOLEAN NOT NULL DEFAULT FALSE,allow_negative BOOLEAN NOT NULL DEFAULT FALSE,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS leave_balances (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),employee_id UUID NOT NULL REFERENCES employees(id) ON DELETE CASCADE,leave_type_id UUID NOT NULL REFERENCES leave_types(id) ON DELETE CASCADE,year INTEGER NOT NULL,opening NUMERIC(6,2) NOT NULL DEFAULT 0,used NUMERIC(6,2) NOT NULL DEFAULT 0,adjustment NUMERIC(6,2) NOT NULL DEFAULT 0,UNIQUE(employee_id,leave_type_id,year));
CREATE TABLE IF NOT EXISTS leave_balance_adjustments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),employee_id UUID NOT NULL REFERENCES employees(id) ON DELETE CASCADE,leave_type_id UUID NOT NULL REFERENCES leave_types(id) ON DELETE CASCADE,year INTEGER NOT NULL,delta NUMERIC(6,2) NOT NULL,note TEXT NOT NULL,adjusted_by UUID REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS leave_requests (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),employee_id UUID NOT NULL REFERENCES employees(id) ON DELETE CASCADE,leave_type_id UUID NOT NULL REFERENCES leave_types(id),start_date DATE NOT NULL,end_date DATE NOT NULL,day_type TEXT NOT NULL DEFAULT 'FULL' CHECK(day_type IN('FULL','FIRST_HALF','SECOND_HALF')),days NUMERIC(6,2) NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','APPROVED','REJECTED','CANCELLED')),manager_comment TEXT,reviewed_by UUID REFERENCES users(id) ON DELETE SET NULL,reviewed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS leave_cancellations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),leave_request_id UUID NOT NULL REFERENCES leave_requests(id) ON DELETE CASCADE,employee_id UUID NOT NULL REFERENCES employees(id) ON DELETE CASCADE,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING',manager_comment TEXT,reviewed_by UUID REFERENCES users(id) ON DELETE SET NULL,reviewed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(leave_request_id,status));
CREATE TABLE IF NOT EXISTS comp_off_credits (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),employee_id UUID NOT NULL REFERENCES employees(id) ON DELETE CASCADE,earned_date DATE NOT NULL,days NUMERIC(5,2) NOT NULL DEFAULT 1,remaining_days NUMERIC(5,2) NOT NULL DEFAULT 1,expires_on DATE NOT NULL,reason TEXT NOT NULL,granted_by UUID REFERENCES users(id) ON DELETE SET NULL,expired_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS wfh_requests (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),employee_id UUID NOT NULL REFERENCES employees(id) ON DELETE CASCADE,work_date DATE NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','APPROVED','REJECTED','CANCELLED')),manager_comment TEXT,reviewed_by UUID REFERENCES users(id) ON DELETE SET NULL,reviewed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(employee_id,work_date));
CREATE TABLE IF NOT EXISTS policies (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),title TEXT NOT NULL,category TEXT,version TEXT NOT NULL DEFAULT '1.0',blob_url TEXT NOT NULL,pathname TEXT NOT NULL,required_ack BOOLEAN NOT NULL DEFAULT FALSE,active BOOLEAN NOT NULL DEFAULT TRUE,uploaded_by UUID REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS policy_acknowledgements (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),policy_id UUID NOT NULL REFERENCES policies(id) ON DELETE CASCADE,employee_id UUID NOT NULL REFERENCES employees(id) ON DELETE CASCADE,acknowledged_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(policy_id,employee_id));
CREATE TABLE IF NOT EXISTS documents (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),employee_id UUID NOT NULL REFERENCES employees(id) ON DELETE CASCADE,document_type TEXT NOT NULL,title TEXT NOT NULL,blob_url TEXT NOT NULL,pathname TEXT NOT NULL,visible_to_employee BOOLEAN NOT NULL DEFAULT TRUE,uploaded_by UUID REFERENCES users(id) ON DELETE SET NULL,expires_on DATE,reminder_days INTEGER NOT NULL DEFAULT 30,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS file_store (id UUID PRIMARY KEY,pathname TEXT NOT NULL,content_type TEXT NOT NULL DEFAULT 'application/octet-stream',size_bytes INTEGER NOT NULL DEFAULT 0,data_base64 TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS resignations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),employee_id UUID NOT NULL REFERENCES employees(id) ON DELETE CASCADE,requested_last_day DATE,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','APPROVED','REJECTED','WITHDRAWN','COMPLETED')),approved_last_day DATE,manager_comment TEXT,clearance_status TEXT NOT NULL DEFAULT 'NOT_STARTED' CHECK(clearance_status IN('NOT_STARTED','IN_PROGRESS','CLEARED')),reviewed_by UUID REFERENCES users(id) ON DELETE SET NULL,reviewed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS employee_checklist_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),employee_id UUID NOT NULL REFERENCES employees(id) ON DELETE CASCADE,checklist_type TEXT NOT NULL CHECK(checklist_type IN('ONBOARDING','OFFBOARDING')),item_key TEXT NOT NULL,label TEXT NOT NULL,completed_at TIMESTAMPTZ,completed_by UUID REFERENCES users(id) ON DELETE SET NULL,note TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(employee_id,checklist_type,item_key));
CREATE TABLE IF NOT EXISTS assets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),asset_tag TEXT NOT NULL UNIQUE,asset_type TEXT NOT NULL,name TEXT NOT NULL,serial_number TEXT,employee_id UUID REFERENCES employees(id) ON DELETE SET NULL,issued_on DATE,returned_on DATE,status TEXT NOT NULL DEFAULT 'AVAILABLE',condition_note TEXT,created_by UUID REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS employee_hr_notes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),employee_id UUID NOT NULL REFERENCES employees(id) ON DELETE CASCADE,note TEXT NOT NULL,created_by UUID REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS holidays (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),holiday_date DATE NOT NULL,name TEXT NOT NULL,region TEXT NOT NULL DEFAULT 'COMPANY' CHECK(region IN('INDIA','US','BOTH','COMPANY')),optional BOOLEAN NOT NULL DEFAULT FALSE,approved BOOLEAN NOT NULL DEFAULT FALSE,approved_by UUID REFERENCES users(id) ON DELETE SET NULL,approved_at TIMESTAMPTZ,active BOOLEAN NOT NULL DEFAULT TRUE,created_by UUID REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(holiday_date,region));
CREATE TABLE IF NOT EXISTS announcements (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),title TEXT NOT NULL,message TEXT NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_by UUID REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS smtp_settings (id INTEGER PRIMARY KEY DEFAULT 1 CHECK(id=1),host TEXT,port INTEGER,secure BOOLEAN NOT NULL DEFAULT FALSE,username TEXT,password_enc TEXT,from_name TEXT,from_email TEXT,updated_by UUID REFERENCES users(id) ON DELETE SET NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS notifications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,message TEXT,link TEXT,read_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS login_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID REFERENCES users(id) ON DELETE SET NULL,event_type TEXT NOT NULL CHECK(event_type IN('LOGIN','LOGOUT','FAILED_LOGIN')),ip_address TEXT,user_agent TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS login_challenges (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,code_hash TEXT NOT NULL,expires_at TIMESTAMPTZ NOT NULL,used_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS audit_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),actor_id UUID REFERENCES users(id) ON DELETE SET NULL,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT,details JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());

CREATE INDEX IF NOT EXISTS idx_attendance_employee_date ON attendance(employee_id,work_date DESC);
CREATE INDEX IF NOT EXISTS idx_leave_requests_status ON leave_requests(status,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_logs_created ON audit_logs(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_documents_employee ON documents(employee_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_holidays_region_date ON holidays(region,holiday_date);
CREATE INDEX IF NOT EXISTS idx_assets_employee ON assets(employee_id,status);
CREATE INDEX IF NOT EXISTS idx_regularization_status ON attendance_regularizations(status,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_comp_off_employee_expiry ON comp_off_credits(employee_id,expires_on);

INSERT INTO attendance_settings(id) VALUES(1) ON CONFLICT DO NOTHING;
